    private MainActivity activity;private LogStore logs;private String shot,roll;private Configuration configuration;
    private long tap=Instant.parse("2026-10-27T00:00:05.123Z").toEpochMilli();
    interface Action{void run()throws Exception;}
    private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private void main(Action action)throws Exception{Throwable[] failure={null};runOnMainSync(()->{try{action.run();}catch(Throwable e){failure[0]=e;}});waitForIdleSync();if(failure[0]!=null)throw new RuntimeException(failure[0]);}
    private Object field(Object owner,String key)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(owner);}
    private void field(Object owner,String key,Object value)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(key);f.setAccessible(true);f.set(owner,value);}
    private Object call(Object owner,String key,Class<?>[] types,Object... args)throws Exception{java.lang.reflect.Method m=owner.getClass().getDeclaredMethod(key,types);m.setAccessible(true);return m.invoke(owner,args);}
    private ExposureEditor editor()throws Exception{return (ExposureEditor)field(activity,"existingEditor");}
    private Bundle draft()throws Exception{return (Bundle)field(activity,"draft");}
    private ViewGroup root()throws Exception{return (ViewGroup)field(activity,"root");}
    private View tag(String key)throws Exception{View v=root().findViewWithTag(key);check(v!=null,"missing tag "+key);return v;}
    private List<View> views(View v){ArrayList<View> result=new ArrayList<>();result.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)result.addAll(views(((ViewGroup)v).getChildAt(i)));return result;}
    private View button(View root,String label){for(View v:views(root))if(v instanceof Button&&label.contentEquals(((Button)v).getText()))return v;throw new AssertionError("missing button "+label);}
    @SuppressWarnings("unchecked") private Dialog dialog()throws Exception{ArrayList<Dialog> list=(ArrayList<Dialog>)field(editor(),"dialogs");for(int i=list.size()-1;i>=0;i--)if(list.get(i).isShowing())return list.get(i);throw new AssertionError("no editor dialog");}
    private View dialogRoot()throws Exception{return dialog().getWindow().getDecorView();}
    private void open()throws Exception{call(activity,"editShot",new Class<?>[]{String.class},shot);check(editor()!=null,"existing editor dispatch");}
    private void openTime()throws Exception{View v=tag("editor-capture-time");((View)v.getParent().getParent()).performClick();}
    private void clickNode(String text)throws Exception{AccessibilityNodeInfo root=null;for(int i=0;i<20&&root==null;i++){root=getUiAutomation().getRootInActiveWindow();if(root==null)SystemClock.sleep(150);}check(root!=null,"active accessible window");for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text))if(text.contentEquals(n.getText())){while(n!=null&&!n.isClickable())n=n.getParent();check(n!=null&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK),"click "+text);return;}throw new AssertionError("missing accessible "+text);}
    private void unchanged(LogStore.Shot before,LogStore.Shot after){check(before.id.equals(after.id)&&before.rollId.equals(after.rollId)&&before.frame==after.frame,"stable identity");check(before.tapped==after.tapped&&before.offset==after.offset&&before.zone==after.zone,"raw time/offset/zone preserved");check(Objects.equals(before.lat,after.lat)&&Objects.equals(before.lon,after.lon)&&Objects.equals(before.accuracy,after.accuracy)&&before.locationTime==after.locationTime&&before.provider.equals(after.provider)&&before.status.equals(after.status),"original location preserved");check(logs.roll(roll).count==1,"edit never creates another exposure");}
    private void interactions()throws Exception{
        main(()->{open();check(!editor().changed()&&!tag("editor-save").isEnabled(),"unchanged editor");check(views(root()).stream().noneMatch(v->v instanceof TextView&&((TextView)v).getText().toString().contains("定位权限 / 设置")),"no live GPS CTA on historical edit");call(activity,"cancelEditor",new Class<?>[]{});check(field(activity,"screen").equals("detail"),"no-op exits without confirmation");open();openTime();});
        main(()->{View r=dialogRoot();r.findViewWithTag("time-adjust:-10").performClick();check(draft().getLong("capturedAt")==tap-10000,"sheet only has local pending time");button(r,"取消").performClick();check(draft().getLong("capturedAt")==tap-10000&&!editor().changed(),"time cancel no change");openTime();r=dialogRoot();r.findViewWithTag("time-date").performClick();DatePickerDialog calendar=(DatePickerDialog)dialog();calendar.getDatePicker().updateDate(2026,9,25);calendar.getButton(-1).performClick();});
        main(()->{View r=dialogRoot();((NumberPicker)r.findViewWithTag("time-0")).setValue(23);((NumberPicker)r.findViewWithTag("time-1")).setValue(59);((NumberPicker)r.findViewWithTag("time-2")).setValue(59);r.findViewWithTag("time-adjust:10").performClick();button(r,"应用到草稿").performClick();check(logs.shot(shot).captured==tap-10000,"applying sheet never writes DB");check(editor().changed(),"time change enables save");tag("editor-save").performClick();LogStore.Shot updated=logs.shot(shot);check(updated.captured!=tap-10000&&updated.timeEdited,"manual timestamp persisted");check(updated.tapped==tap&&updated.offset==-10,"manual time does not rewrite origin");check(activity.getPreferences(0).getInt("offset",99)==17,"global default untouched");});
        main(()->{open();long captured=draft().getLong("capturedAt");openTime();dialogRoot().findViewWithTag("time-adjust:1").performClick();Bundle pending=draft();Bundle instance=new Bundle();activity.onSaveInstanceState(instance);check(instance.getBundle("draft").getBundle("timeDraft").getLong("value")==captured+1000,"pending time serialized in activity state");editor().dispose();call(activity,"showEditor",new Class<?>[]{});check(draft()==pending&&draft().getBundle("timeDraft").getLong("value")==captured+1000,"pending time survives view recreation");});
        main(()->{check(dialogRoot().findViewWithTag("time-preview")!=null,"time sheet reopens");button(dialogRoot(),"取消").performClick();tag("editor-aperture").performClick();AlertDialog choices=(AlertDialog)dialog();choices.getListView().performItemClick(null,1,1);});
        main(()->{check(draft().getString("aperture").equals("1"),"native aperture choice");tag("editor-aperture").performClick();AlertDialog choices=(AlertDialog)dialog();choices.getButton(-3).performClick();});
        main(()->{AlertDialog custom=(AlertDialog)dialog();EditText input=null;for(View v:views(dialogRoot()))if(v instanceof EditText)input=(EditText)v;check(input!=null,"custom aperture input");input.setText("0");custom.getButton(-1).performClick();check(custom.isShowing()&&input.getError()!=null,"invalid parameter stays open");input.setText("9.5");custom.getButton(-1).performClick();});
        main(()->{check(draft().getString("aperture").equals("9.5"),"custom aperture retained");call(editor(),"applyValues",new Class<?>[]{String.class,String.class,String.class,String.class,String.class},"","1/125","","","");check(draft().getString("aperture").equals("9.5")&&draft().getString("lens").equals("Nikkor 50mm"),"empty preset fields preserve draft");String raw=draft().getString("memo");check(raw.equals("  ISO 400 • #Portrait • 原样备注  "),"legacy memo untouched during parameter edits");tag("editor-save").performClick();check(logs.shot(shot).aperture.equals("9.5")&&logs.shot(shot).timeEdited&&logs.shot(shot).memo.equals(raw),"parameter-only save keeps manual timestamp and raw memo");open();call(editor(),"menu",new Class<?>[]{});((AlertDialog)dialog()).getListView().performItemClick(null,0,0);check(draft().getString("lens").isEmpty()&&draft().getString("memo").equals(raw),"clear only parameters");});
        main(()->call(activity,"cancelEditor",new Class<?>[]{}));clickNode("放弃");waitForIdleSync();
        main(()->{check(logs.shot(shot).aperture.equals("9.5"),"discard keeps saved parameters");open();draft().putBoolean("tagsOpen",true);call(editor(),"tagSheet",new Class<?>[]{});});clickNode("风景");waitForIdleSync();main(()->((AlertDialog)dialog()).getButton(-1).performClick());main(()->{check(draft().getString("memo").contains("#Landscape"),"tag selection remains in notes group");tag("editor-quick-fill").performClick();});
        main(()->{check(dialogRoot()!=null,"quick sheet opens");button(dialogRoot(),"最近使用").performClick();});
        main(()->{check(draft().getBoolean("quickPresets",true)==false,"recent tab");button(dialogRoot(),"参数预设").performClick();});
        main(()->{button(dialogRoot(),"管理预设 ›").performClick();((AlertDialog)dialog()).getButton(-1).performClick();});
        main(()->{check(draft().containsKey("presetForm"),"custom preset form reachable");editor().dispose();call(activity,"showEditor",new Class<?>[]{});});
        main(()->{check(field(editor(),"presetEditor")!=null,"custom preset form draft restored");((PresetEditor)field(editor(),"presetEditor")).dispose();draft().remove("presetForm");call(activity,"showEditor",new Class<?>[]{});});
        Intent[] launched={null};ActivityMonitor monitor=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent intent){launched[0]=new Intent(intent);return new ActivityResult(Activity.RESULT_CANCELED,null);}};addMonitor(monitor);
        try{main(()->{tag("editor-quick-fill").performClick();button(dialogRoot(),"测光填入 ›").performClick();check(launched[0].getBooleanExtra("return_exposure",false)&&!launched[0].getBooleanExtra("record_now",false),"meter fills existing parameters without creating exposure");});
        main(()->{long time=draft().getLong("capturedAt");String note=draft().getString("memo");call(activity,"onActivityResult",new Class<?>[]{int.class,int.class,Intent.class},21,Activity.RESULT_OK,new Intent().putExtra("aperture","11").putExtra("shutter","1/30").putExtra("meter_iso",100).putExtra("filter_note","ND 3 stops"));check(draft().getLong("capturedAt")==time&&draft().getString("memo").equals(note)&&draft().getString("filters").contains("ND 3 stops"),"tool return preserves memo/time while filling parameters/filter");tag("editor-save").performClick();});}finally{removeMonitor(monitor);}
    }
    private byte[] archive(JSONObject manifest)throws Exception{ByteArrayOutputStream result=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(result)){zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(manifest.toString().getBytes("UTF-8"));zip.closeEntry();}return result.toByteArray();}
    private void persistence()throws Exception{
        LogStore.Shot before=logs.shot(shot);ByteArrayOutputStream bytes=new ByteArrayOutputStream();FilmBackup.write(activity,logs,bytes);
        try(FilmBackup.Prepared p=FilmBackup.inspect(activity,new ByteArrayInputStream(bytes.toByteArray()))){check(p.manifest.getInt("schema")==25,"new backup schema22");JSONObject s=p.manifest.getJSONArray("shots").getJSONObject(0);check(s.getInt("time_edited")==1&&s.getLong("captured_at")==before.captured,"archive edited time");int count=logs.rolls().size();for(Object flag:new Object[]{-1,2,"1",.5,JSONObject.NULL}){s.put("time_edited",flag);try{FilmBackup.restore(activity,logs,p);throw new AssertionError("invalid flag accepted "+flag);}catch(Exception expected){}check(logs.rolls().size()==count,"failed restore atomic");}s.put("time_edited",1);for(Object bad:new Object[]{Long.MAX_VALUE,"123",.5}){s.put("captured_at",bad);boolean rejected=false;try{FilmBackup.validate(p);}catch(Exception expected){rejected=true;}check(rejected,"invalid manual time rejected");}s.put("captured_at",before.captured);FilmBackup.restore(activity,logs,p);check(logs.rolls().size()==count+1,"new backup restores");boolean matched=false;for(LogStore.Roll r:logs.rolls())for(LogStore.Shot row:logs.shots(r.id))if(!row.id.equals(shot)&&row.timeEdited){matched=true;check(row.captured==before.captured&&row.tapped==before.tapped&&row.offset==before.offset,"restored edited semantics");}check(matched,"restored record found");
            JSONObject legacy=new JSONObject(p.manifest.toString());legacy.put("schema",21);JSONObject old=legacy.getJSONArray("shots").getJSONObject(0);old.remove("time_edited");old.put("captured_at",tap-10000);try(FilmBackup.Prepared prepared=FilmBackup.inspect(activity,new ByteArrayInputStream(archive(legacy)))){check(prepared.manifest.getJSONArray("shots").getJSONObject(0).getInt("time_edited")==0,"schema21 normalizes default flag");FilmBackup.restore(activity,logs,prepared);}
        }
        File file=new File(activity.getCacheDir(),"edited-time-export.csv");main(()->call(activity,"onActivityResult",new Class<?>[]{int.class,int.class,Intent.class},2,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(file))));String csv=new String(java.nio.file.Files.readAllBytes(file.toPath()),"UTF-8");check(csv.contains("time_edited")&&csv.contains(Instant.ofEpochMilli(before.captured).toString()),"actual activity CSV emits final time/flag");CsvImport.Preview preview=CsvImport.parse(new StringReader(csv));JSONObject edited=null;JSONArray all=preview.data.manifest.getJSONArray("shots");for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getInt("time_edited")==1)edited=all.getJSONObject(i);check(edited!=null&&edited.getLong("captured_at")==before.captured,"CSV parser retains manual timestamp");FilmBackup.restore(activity,logs,preview.data);
        LogStore.Shot after=logs.shot(shot);unchanged(before,after);
        Context oldContext=new WorkspaceContext(Workspace.root(activity),UUID.randomUUID().toString());String id;try(LogStore old=new LogStore(oldContext)){String r=old.addRoll("Migration","Test","",400,36);id=old.insert(r,tap,-10,480,"denied","8","1/250","","","","");old.getWritableDatabase().execSQL("ALTER TABLE shots DROP COLUMN time_edited");old.getWritableDatabase().setVersion(20);}try(LogStore migrated=new LogStore(oldContext)){LogStore.Shot s=migrated.shot(id);check(migrated.getReadableDatabase().getVersion()==24&&!s.timeEdited&&s.captured==tap-10000,"real DB20 upgrade preserves time and defaults flag0");}
    }
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private void screenshot(View view,String name)throws Exception{Bitmap image=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.getViewTreeObserver().dispatchOnPreDraw();view.draw(new Canvas(image));
File dir=new File(activity.getExternalFilesDir(null),"exposure-editor");dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}
    @SuppressWarnings("deprecation") private void layouts()throws Exception{
        for(boolean dark:new boolean[]{false,true})for(int width:new int[]{320,375,414,768}){
            Configuration c=new Configuration(configuration);c.uiMode=(c.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);c.fontScale=dark?1.6f:1f;c.screenWidthDp=width;activity.getResources().updateConfiguration(c,activity.getResources().getDisplayMetrics());open();ViewGroup root=root();root.measure(View.MeasureSpec.makeMeasureSpec(dp(width),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(dp(740),View.MeasureSpec.EXACTLY));root.layout(0,0,root.getMeasuredWidth(),root.getMeasuredHeight());View a=tag("editor-aperture"),s=tag("editor-shutter"),save=tag("editor-save");check(Math.abs(a.getWidth()-s.getWidth())<=1&&a.getHeight()==s.getHeight()&&a.getTop()==s.getTop(),"equal parameter cells "+width);check(a.getHeight()>=dp(82),"parameter values must not be clipped by divider");check(save.getWidth()<=root.getWidth()&&save.getHeight()>=dp(48),"save fits "+width);for(View v:views(editor().view()))if(v instanceof EditText&&v.isShown())check(v.getWidth()>0,"visible input measured");screenshot(root,(dark?"dark-large-":"light-")+width);
        }
        activity.getResources().updateConfiguration(configuration,activity.getResources().getDisplayMetrics());open();
    }
    private void captureWindow(String name)throws Exception{Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"window "+name);try(FileOutputStream stream=new FileOutputStream(new File(activity.getExternalFilesDir(null),"exposure-editor/"+name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}finally{image.recycle();}}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle out=new Bundle();Context c=getTargetContext();String previous=Workspace.current(c);boolean passed=false;try{
        check(c.getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated package");String space=UUID.randomUUID().toString();Workspace.activate(c,space);Context isolated=new WorkspaceContext(Workspace.root(c),space);
        try(LogStore fixture=new LogStore(isolated)){roll=fixture.addRoll("Editor fixture","Kodak Ultramax 400","Nikon FE2",400,36);shot=fixture.insert(roll,tap,-10,480,"denied","8","1/250","Nikkor 50mm","  ISO 400 • #Portrait • 原样备注  ","+1","ND8");android.content.ContentValues location=new android.content.ContentValues();location.put("latitude",31.23);location.put("longitude",121.47);location.put("accuracy_m",15);location.put("location_time",tap-3000);location.put("provider","gps");location.put("status","acquired");fixture.getWritableDatabase().update("shots",location,"id=?",new String[]{shot});}
        activity=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));configuration=new Configuration(activity.getResources().getConfiguration());waitForIdleSync();LogStore.Shot[] original={null};main(()->{logs=(LogStore)field(activity,"store");field(activity,"rollId",roll);activity.getPreferences(0).edit().putInt("offset",17).commit();original[0]=logs.shot(shot);});interactions();main(()->unchanged(original[0],logs.shot(shot)));persistence();main(this::layouts);
        SystemClock.sleep(8500);Bitmap actual=getUiAutomation().takeScreenshot();check(actual!=null,"actual window screenshot");File path=new File(activity.getExternalFilesDir(null),"exposure-editor/actual-window.png");try(FileOutputStream stream=new FileOutputStream(path)){actual.compress(Bitmap.CompressFormat.PNG,100,stream);}actual.recycle();
        main(()->openTime());SystemClock.sleep(250);captureWindow("actual-time-sheet");main(()->button(dialogRoot(),"取消").performClick());main(()->tag("editor-quick-fill").performClick());SystemClock.sleep(250);captureWindow("actual-quick-fill");main(()->{for(View v:views(dialogRoot()))if(v instanceof ScrollView){((ScrollView)v).fullScroll(View.FOCUS_DOWN);break;}});SystemClock.sleep(350);captureWindow("actual-quick-fill-bottom");main(()->button(dialogRoot(),"取消").performClick());
        main(()->((ScrollView)field(editor(),"page")).fullScroll(View.FOCUS_DOWN));SystemClock.sleep(250);captureWindow("actual-notes");main(()->{EditText memo=(EditText)tag("editor-memo");memo.requestFocus();((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(memo,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});SystemClock.sleep(700);main(()->{Rect visible=new Rect(),bounds=new Rect();root().getWindowVisibleDisplayFrame(visible);check(tag("editor-save").getGlobalVisibleRect(bounds)&&bounds.bottom<=visible.bottom,"save remains in visible viewport with focused notes");});captureWindow("actual-notes-keyboard");main(()->call(activity,"hideKeyboard",new Class<?>[]{}));
        main(()->{Configuration dark=new Configuration(configuration);dark.uiMode=(dark.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|Configuration.UI_MODE_NIGHT_YES;dark.fontScale=1.6f;activity.getResources().updateConfiguration(dark,activity.getResources().getDisplayMetrics());open();openTime();});SystemClock.sleep(250);captureWindow("actual-dark-large-time");main(()->button(dialogRoot(),"取消").performClick());
        out.putString("stream","PASS: existing editor no-op/discard/save; native date/time sheet cancel/apply/recreation; custom invalid/valid parameter; nonempty quick fill; raw memo and original identity/time/GPS preserved; no new exposure/global-offset write; preset manager and meter return flags/filter; DB20-to21; schema22 and legacy21 restore; invalid flag/time rejection and atomic restore; actual CSV export/parse/restore; native 320/375/414/768 light and dark1.6 layouts. Synthetic fixture, not physical-device acceptance.\n");passed=true;
    }catch(Throwable error){out.putString("stream",android.util.Log.getStackTraceString(error));}finally{try{if(activity!=null)main(()->{if(configuration!=null)activity.getResources().updateConfiguration(configuration,activity.getResources().getDisplayMetrics());activity.finish();});}catch(Exception ignored){}Workspace.activate(c,previous);}finish(passed?-1:0,out);}
